23	
24	import java.util.*;
25	
26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "postcode")
46	    private String postcode;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: '+' followed by 8 to 15 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private java.time.LocalDate registrationDate;
58	
59	    @Column(name = "birth_date", columnDefinition = "DATE")
60	    private java.time.LocalDate birthDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "household_size")
72	    private Integer householdSize;
73	
74	    @Column(name = "bulk_signup_warning")
75	    private boolean bulkSignupWarning;
76	
77	    @Column(name = "possible_duplicate")
78	    private boolean possibleDuplicate;
79	
80	    @Column(name = "possible_duplicate_of")
81	    private Integer possibleDuplicateOf;
82	
83	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
84	    private Set<Pet> pets;
85	
86	    public String getAddress() {
87	        return this.address;
88	    }
89	
90	    public void setAddress(String address) {
91	        this.address = address;
92	    }
93	
94	    public String getCity() {
95	        return this.city;
96	    }
97	
98	    public void setCity(String city) {
99	        this.city = city;
100	    }
101	
102	    public String getPostcode() {
103	        return this.postcode;
104	    }
105	
106	    public void setPostcode(String postcode) {
107	        this.postcode = postcode;
108	    }
109	
110	    public String getTelephone() {
111	        return this.telephone;
112	    }
113	
114	    public void setTelephone(String telephone) {
115	        this.telephone = telephone;
116	    }
117	
118	    public String getEmail() {
119	        return this.email;
120	    }
121	
122	    public void setEmail(String email) {
123	        this.email = email;
124	    }
125	
126	    public java.time.LocalDate getRegistrationDate() {
127	        return this.registrationDate;
128	    }
129	
130	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
131	        this.registrationDate = registrationDate;
132	    }
133	
134	    public java.time.LocalDate getBirthDate() {
135	        return this.birthDate;
136	    }
137	
138	    public void setBirthDate(java.time.LocalDate birthDate) {
139	        this.birthDate = birthDate;
140	    }
141	
142	    public String getCustomerCode() {
143	        return this.customerCode;
144	    }
145	
146	    public void setCustomerCode(String customerCode) {
147	        this.customerCode = customerCode;
148	    }
149	
150	    public String getHouseholdId() {
151	        return this.householdId;
152	    }
153	
154	    public void setHouseholdId(String householdId) {
155	        this.householdId = householdId;
156	    }
157	
158	    public Integer getNamesakeCount() {
159	        return this.namesakeCount;
160	    }
161	
162	    public void setNamesakeCount(Integer namesakeCount) {
163	        this.namesakeCount = namesakeCount;
164	    }
165	
166	    public Integer getHouseholdSize() {
167	        return this.householdSize;
168	    }
169	
170	    public void setHouseholdSize(Integer householdSize) {
171	        this.householdSize = householdSize;
172	    }
173	
174	    public boolean isBulkSignupWarning() {
175	        return this.bulkSignupWarning;
176	    }
177	
178	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
179	        this.bulkSignupWarning = bulkSignupWarning;
180	    }
181	
182	    public boolean isPossibleDuplicate() {
183	        return this.possibleDuplicate;
184	    }
185	
186	    public void setPossibleDuplicate(boolean possibleDuplicate) {
187	        this.possibleDuplicate = possibleDuplicate;
188	    }
189	
190	    public Integer getPossibleDuplicateOf() {
191	        return this.possibleDuplicateOf;
192	    }
193	
194	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
195	        this.possibleDuplicateOf = possibleDuplicateOf;
196	    }
197	
198	    protected Set<Pet> getPetsInternal() {
199	        if (this.pets == null) {
200	            this.pets = new HashSet<>();
201	        }
202	        return this.pets;
203	    }
204	
205	    protected void setPetsInternal(Set<Pet> pets) {
206	        this.pets = pets;
207	    }
208	
209	    public List<Pet> getPets() {
210	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
211	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
212	        return Collections.unmodifiableList(sortedPets);
213	    }
214	
215	    public void setPets(List<Pet> pets) {
216	        this.pets = new HashSet<>(pets);
217	    }
218	
219	    public void addPet(Pet pet) {
220	        getPetsInternal().add(pet);
221	        pet.setOwner(this);
222	    }
223	
224	    /**
225	     * Return the Pet with the given name, or null if none found for this Owner.
226	     *
227	     * @param name to test
228	     * @return true if pet name is already in use
229	     */
230	    public Pet getPet(String name) {
231	        return getPet(name, false);
232	    }
233	
234	    /**
235	     * Return the Pet with the given name, or null if none found for this Owner.
236	     *
237	     * @param name to test
238	     * @return true if pet name is already in use
239	     */
240	    public Pet getPet(String name, boolean ignoreNew) {
241	        name = name.toLowerCase();
242	        for (Pet pet : getPetsInternal()) {
243	            if (!ignoreNew || !pet.isNew()) {
244	                String compName = pet.getName();
245	                compName = compName.toLowerCase();
246	                if (compName.equals(name)) {
247	                    return pet;
248	                }
249	            }
250	        }
251	        return null;
252	    }
253	
254	    public Pet getPet(Integer petId) {
255	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
256	    }
257	
258	    @Override
259	    public String toString() {
260	        return new ToStringCreator(this)
261	
262	            .append("id", this.getId())
263	            .append("new", this.isNew())
264	            .append("lastName", this.getLastName())
265	            .append("firstName", this.getFirstName())
266	            .append("address", this.address)
267	            .append("city", this.city)
268	            .append("telephone", this.telephone)
269	            .toString();
270	    }
271	}
