20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "checkDigit",
26	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckDigit.of(owner.getCustomerCode()))")
27	    @Mapping(target = "membershipNumber",
28	        expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
29	    @Mapping(target = "membershipPoints",
30	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipLevel.points(owner))")
31	    @Mapping(target = "membershipLevel",
32	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipLevel.of(owner))")
33	    @Mapping(target = "locality",
34	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.CustomerCode.region(owner.getCustomerCode()))")
35	    @Mapping(target = "timezone",
36	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.Locality.timezone(org.springframework.samples.petclinic.rest.function.owner.CustomerCode.region(owner.getCustomerCode())))")
37	    @Mapping(target = "contactPreference",
38	        expression = "java(OwnerDto.ContactPreferenceEnum.fromValue(org.springframework.samples.petclinic.rest.function.owner.ContactPreference.of(owner)))")
39	    @Mapping(target = "identityKey",
40	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
41	    @Mapping(target = "ageBand",
42	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner))")
43	    @Mapping(target = "telephoneDisplay",
44	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.of(owner.getTelephone()))")
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    Owner toOwner(OwnerDto ownerDto);
48	
49	    @Mapping(target = "id", ignore = true)
50	    @Mapping(target = "pets", ignore = true)
51	    Owner toOwner(OwnerFieldsDto ownerDto);
52	
53	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
54	
55	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
56	
57	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
58	        OwnerPageDto ownerPageDto = new OwnerPageDto();
59	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
60	        ownerPageDto.setPage(ownerPage.getNumber());
61	        ownerPageDto.setSize(ownerPage.getSize());
62	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
63	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
64	        return ownerPageDto;
65	    }
66	}
