1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single home for owner address normalization. The create pipeline's {@link BuildOwner}
8	 * (which stores the canonical form and rejects an address blank after normalization) and
9	 * {@link Household} (which matches household members and derives the shared household id) both
10	 * go through here, so the stored form and every address comparison stay defined in one place.
11	 */
12	final class AddressNormalizer {
13	
14	    private AddressNormalizer() {
15	    }
16	
17	    /** Common street-type abbreviations expanded to their canonical (upper-cased) word. */
18	    private static final Map<String, String> ABBREVIATIONS = Map.of(
19	            "ST", "STREET",
20	            "RD", "ROAD",
21	            "AVE", "AVENUE");
22	
23	    /**
24	     * Canonical stored form of a supplied address: leading/trailing and repeated whitespace
25	     * collapsed to single spaces, upper-cased, then each whitespace-delimited word that is a
26	     * known abbreviation expanded ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
27	     * {@code AVE}->{@code AVENUE}). So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
28	     * A {@code null} or all-whitespace address normalizes to the empty string.
29	     */
30	    static String normalize(String address) {
31	        if (address == null) {
32	            return "";
33	        }
34	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
35	        if (collapsed.isEmpty()) {
36	            return "";
37	        }
38	        String[] words = collapsed.split(" ");
39	        StringBuilder sb = new StringBuilder(collapsed.length());
40	        for (int i = 0; i < words.length; i++) {
41	            if (i > 0) {
42	                sb.append(' ');
43	            }
44	            sb.append(ABBREVIATIONS.getOrDefault(words[i], words[i]));
45	        }
46	        return sb.toString();
47	    }
48	}
