1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's 'locality' (canonical region). The postcode is preferred: a
7	 * 4-digit postcode falling in a known region range (NSW 2000-2099, VIC 3000-3099,
8	 * QLD 4000-4099) yields that region. Only when the postcode is absent or in no known
9	 * range does it fall back to the fixed city-to-region table. Any city not in the table
10	 * — including a null city — yields "UNKNOWN".
11	 */
12	public final class Locality {
13	
14	    /** City -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    /** Region -> inclusive 4-digit postcode range {low, high}. */
19	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
20	            "NSW", new int[] {2000, 2099},
21	            "VIC", new int[] {3000, 3099},
22	            "QLD", new int[] {4000, 4099});
23	
24	    /** Region -> IANA timezone name. */
25	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
26	            "NSW", "Australia/Sydney",
27	            "VIC", "Australia/Melbourne",
28	            "QLD", "Australia/Brisbane");
29	
30	    /** Sentinel returned by {@link #of(String)} for a city with no known region. */
31	    public static final String UNKNOWN = "UNKNOWN";
32	
33	    private Locality() {
34	    }
35	
36	    /** A syntactically valid postcode is exactly 4 digits. */
37	    private static final java.util.regex.Pattern FOUR_DIGITS = java.util.regex.Pattern.compile("\\d{4}");
38	
39	    /** Canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
40	    public static String of(String city) {
41	        return city == null ? UNKNOWN : CITY_REGION.getOrDefault(city, UNKNOWN);
42	    }
43	
44	    /**
45	     * Canonical region for an owner, preferring the {@code postcode}: when it falls in a known
46	     * region range this returns that region, disambiguating cities that share a name. Otherwise
47	     * (postcode absent or in no known range) it falls back to the city-to-region table via
48	     * {@link #of(String)}.
49	     */
50	    public static String of(String city, String postcode) {
51	        String byPostcode = regionForPostcode(postcode);
52	        return byPostcode != null ? byPostcode : of(city);
53	    }
54	
55	    /**
56	     * The region whose inclusive postcode range contains {@code postcode}, or {@code null} when
57	     * the postcode is absent, not 4 digits, or in no known range.
58	     */
59	    public static String regionForPostcode(String postcode) {
60	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
61	            return null;
62	        }
63	        int value = Integer.parseInt(postcode);
64	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
65	            int[] range = entry.getValue();
66	            if (value >= range[0] && value <= range[1]) {
67	                return entry.getKey();
68	            }
69	        }
70	        return null;
71	    }
72	
73	    /**
74	     * The inclusive 4-digit postcode range {low, high} for {@code region}, or {@code null}
75	     * when the region has no known range (so any 4-digit postcode is acceptable).
76	     */
77	    public static int[] postcodeRange(String region) {
78	        return REGION_POSTCODES.get(region);
79	    }
80	
81	    /**
82	     * The IANA timezone name for {@code region} via the fixed region-to-timezone table
83	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane), or
84	     * {@code null} when the region is absent or not in the table.
85	     */
86	    public static String timezone(String region) {
87	        return region == null ? null : REGION_TIMEZONE.get(region);
88	    }
89	}
