2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Single home for the SHA-256 hex hashing the create pipeline uses to derive stable identifiers.
10	 * Both {@link CustomerCode} (the {@code HASH8} segment of the customer code) and
11	 * {@link Household} (the shared household id) go through here, so the hashing stays defined in one
12	 * place.
13	 */
14	final class ShaHex {
15	
16	    private ShaHex() {
17	    }
18	
19	    /**
20	     * The first {@code length} UPPER-case hex characters of SHA-256 over the UTF-8 bytes of
21	     * {@code value}. Used to derive short, stable identifiers from a canonical input string.
22	     */
23	    static String upperPrefix(String value, int length) {
24	        return sha256Hex(value).substring(0, length).toUpperCase(Locale.ROOT);
25	    }
26	
27	    private static String sha256Hex(String value) {
28	        try {
29	            byte[] digest = MessageDigest.getInstance("SHA-256")
30	                    .digest(value.getBytes(StandardCharsets.UTF_8));
31	            StringBuilder sb = new StringBuilder(digest.length * 2);
32	            for (byte b : digest) {
33	                sb.append(String.format("%02x", b));
34	            }
35	            return sb.toString();
36	        }
37	        catch (NoSuchAlgorithmException e) {
38	            throw new IllegalStateException("SHA-256 not available", e);
39	        }
40	    }
41	}
