9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
14	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
15	import org.springframework.samples.petclinic.rest.escalation.RegistrationDateInFutureException;
16	import org.springframework.validation.annotation.Validated;
17	import org.springframework.web.bind.annotation.RequestBody;
18	
19	@Validated
20	public class BuildOwner {
21	
22	    /** Simple syntactic email check: non-space local part, '@', non-space domain with a dot. */
23	    private static final java.util.regex.Pattern EMAIL =
24	            java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
25	
26	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper,
27	            OwnerRepository ownerRepository, Out<Owner> built, Out<Boolean> sharesHousehold)
28	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
29	            RegistrationDateInFutureException {
30	        // Normalize the address up front so the required-field check rejects an address that is
31	        // blank once trimmed/collapsed, and every later step (and the stored value) sees the
32	        // canonical form.
33	        String normalizedAddress = canonicalizeAddress(request);
34	        requireFields(request, normalizedAddress);
35	        request.setTelephone(TelephoneNormalizer.normalize(request.getTelephone()));
36	        request.setEmail(normalizeEmail(request.getEmail()));
37	        Owner owner = ownerMapper.toOwner(request);
38	        // The EFFECTIVE registration date (supplied or defaulted to the server date) must fall on
39	        // a business day: a Saturday or Sunday rolls forward to the next Monday. Every value
40	        // derived from the registration date (e.g. the membership number's year segment, the daily
41	        // create-limit's day) then uses this adjusted date.
42	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
43	        java.time.LocalDate serverDate = java.time.LocalDate.now();
44	        if (registrationDate == null) {
45	            registrationDate = serverDate;
46	        } else if (registrationDate.isAfter(serverDate)) {
47	            // A supplied registration date cannot be in the future.
48	            throw new RegistrationDateInFutureException(registrationDate, serverDate);
49	        }
50	        owner.setRegistrationDate(toBusinessDay(registrationDate));
51	        owner.setCustomerCode(CustomerCode.of(owner));
52	        built.set(owner);
53	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
54	    }
55	
56	    /**
57	     * Canonicalize the address supplied on the request: normalize it to the stored form and write
58	     * it back onto the request (so the mapped owner and every later step see the canonical value),
59	     * returning that normalized form for the required-field check.
60	     */
61	    private static String canonicalizeAddress(OwnerFieldsDto request) {
62	        String normalizedAddress = AddressNormalizer.normalize(request.getAddress());
63	        request.setAddress(normalizedAddress);
64	        return normalizedAddress;
65	    }
66	
67	    /**
68	     * Enforce the owner's required fields, collecting every missing one so the caller reports them
69	     * together. {@code normalizedAddress} is the already-canonicalized address, so an address blank
70	     * once trimmed/collapsed counts as missing.
71	     */
72	    private static void requireFields(OwnerFieldsDto request, String normalizedAddress)
73	            throws MissingOwnerFieldsException {
74	        List<String> missing = new ArrayList<>();
75	        if (isBlank(request.getFirstName())) {
76	            missing.add("firstName");
77	        }
78	        if (isBlank(request.getLastName())) {
79	            missing.add("lastName");
80	        }
81	        if (normalizedAddress.isEmpty()) {
82	            missing.add("address");
83	        }
84	        if (isBlank(request.getCity())) {
85	            missing.add("city");
86	        }
87	        if (isBlank(request.getTelephone())) {
88	            missing.add("telephone");
89	        }
90	        if (!missing.isEmpty()) {
91	            throw new MissingOwnerFieldsException(missing);
92	        }
93	    }
94	
95	    /**
96	     * Roll a registration date off the weekend: a Saturday or Sunday moves forward to the next
97	     * Monday; a weekday is returned unchanged.
98	     */
99	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
100	        switch (date.getDayOfWeek()) {
101	            case SATURDAY:
102	                return date.plusDays(2);
103	            case SUNDAY:
104	                return date.plusDays(1);
105	            default:
106	                return date;
107	        }
108	    }
109	
110	    /** When present, require a syntactically valid address and store it lower-cased; else reject with 400. */
111	    private static String normalizeEmail(String email) throws InvalidEmailException {
112	        if (email == null || email.isBlank()) {
113	            return null;
114	        }
115	        String trimmed = email.trim();
116	        if (!EMAIL.matcher(trimmed).matches()) {
117	            throw new InvalidEmailException(email);
118	        }
119	        return trimmed.toLowerCase(java.util.Locale.ROOT);
120	    }
121	
122	    private static boolean isBlank(String value) {
123	        return value == null || value.isBlank();
124	    }
125	}
